template <typename UnionPtrType>
BidderWorkletKAnonEnforcedBidPtr BidderWorkletKAnonEnforcedBid::Clone() const {
  switch (tag_) {
    case Tag::kSameAsNonEnforced:
      return NewSameAsNonEnforced(
          mojo::Clone(*data_.same_as_non_enforced));
    case Tag::kBid:
      return NewBid(
          mojo::Clone(*data_.bid));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, BidderWorkletKAnonEnforcedBid>::value>::type*>
bool BidderWorkletKAnonEnforcedBid::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kSameAsNonEnforced:
      return mojo::Equals(*(data_.same_as_non_enforced), *(other.data_.same_as_non_enforced));
    case Tag::kBid:
      return mojo::Equals(*(data_.bid), *(other.data_.bid));
  }

  return false;
}
